<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\PDO;
use App\Domain\Generations\Generation;use App\Domain\Generations\GenerationId;use App\Domain\Generations\GenerationRepository;use PDO;
final class PdoGenerationRepository implements GenerationRepository { public function __construct(private PDO $pdo) {} public function nextId(): GenerationId { return GenerationId::new(); } public function save(Generation $g): void { $sql='INSERT INTO generations (id,user_id,type,subject,topic,details,grade,duration,lang,prompt,status,result_md,result_json,created_at,updated_at) VALUES (:id,:userId,:type,:subject,:topic,:details,:grade,:duration,:lang,:prompt,:status,:resultMd,:resultJson,:createdAt,:updatedAt) ON CONFLICT(id) DO UPDATE SET type=excluded.type,subject=excluded.subject,topic=excluded.topic,details=excluded.details,grade=excluded.grade,duration=excluded.duration,lang=excluded.lang,prompt=excluded.prompt,status=excluded.status,result_md=excluded.result_md,result_json=excluded.result_json,updated_at=excluded.updated_at'; $st=$this->pdo->prepare($sql); $st->execute(['id'=>$g->id()->value(),'userId'=>$g->userId(),'type'=>$g->type(),'subject'=>$g->subject(),'topic'=>$g->topic(),'details'=>$g->details(),'grade'=>$g->grade(),'duration'=>$g->duration(),'lang'=>$g->lang(),'prompt'=>$g->prompt(),'status'=>$g->status(),'resultMd'=>$g->resultMd(),'resultJson'=>$g->resultJson(),'createdAt'=>$g->createdAt()->format(DATE_ATOM),'updatedAt'=>$g->updatedAt()->format(DATE_ATOM)]); } public function listByUser(string $userId): array { $st=$this->pdo->prepare('SELECT * FROM generations WHERE user_id=:userId ORDER BY updated_at DESC'); $st->execute(['userId'=>$userId]); $rows=$st->fetchAll(); return array_map(fn(array $r)=>$this->hydrate($r),$rows); } public function byId(GenerationId $id): ?Generation { $st=$this->pdo->prepare('SELECT * FROM generations WHERE id=:id'); $st->execute(['id'=>$id->value()]); $row=$st->fetch(); return $row===false?null:$this->hydrate($row);} public function delete(GenerationId $id): void { $st=$this->pdo->prepare('DELETE FROM generations WHERE id=:id'); $st->execute(['id'=>$id->value()]); } private function hydrate(array $r): Generation { return Generation::reconstitute(GenerationId::fromString((string)$r['id']),(string)$r['user_id'],(string)($r['type'] ?? 'lesson_plan'),(string)$r['subject'],(string)$r['topic'],(string)$r['details'],(string)$r['grade'],(int)$r['duration'],(string)$r['lang'],(string)$r['prompt'],(string)$r['status'],$r['result_md']!==null?(string)$r['result_md']:null,$r['result_json']!==null?(string)$r['result_json']:null,new \DateTimeImmutable((string)$r['created_at']),new \DateTimeImmutable((string)$r['updated_at'])); }}
